function copyModelIds(e){return[...new Set(e.map(e=>e.trim()).filter(Boolean))]}function copyProviderCatalogOutcomes(e){return(e?.outcomes??[]).map(e=>{const t={provider:e.provider.trim(),status:e.status};if(e.profileId)t.profileId=e.profileId.trim();if(e.rejectionScope)t.rejectionScope=e.rejectionScope;if(e.status===`ready`){if(e.modelAccessPrograms)t.modelAccessPrograms=e.modelAccessPrograms.map(e=>({...e,cyber:[...e.cyber]}));if(e.modelServiceTiers)t.modelServiceTiers=e.modelServiceTiers.map(e=>({modelId:e.modelId.trim(),runtimeId:e.runtimeId.trim(),api:e.api.trim(),baseUrl:e.baseUrl.trim(),serviceTiers:copyModelIds(e.serviceTiers)}));const n=e.modelOrder?copyModelIds(e.modelOrder):[];if(n.length>0)t.modelOrder=n;if(e.listedModelIds)t.listedModelIds=copyModelIds(e.listedModelIds);if(e.modelIdCatalog){t.modelIdCatalog={baseUrl:e.modelIdCatalog.baseUrl,modelIds:copyModelIds(e.modelIdCatalog.modelIds)};if(e.modelIdCatalog.aliases)t.modelIdCatalog.aliases=copyModelIds(e.modelIdCatalog.aliases)}}return t})}function readProviderCatalogResultEntries(e){const t=e.result;if(!t)return[];return`provider`in t?[e.providerId,...e.aliases??[]].map(e=>[e,t.provider]):Object.entries(t.providers)}export{readProviderCatalogResultEntries as n,copyProviderCatalogOutcomes as t};